const test = require('node:test');
const assert = require('node:assert/strict');
const { searchLink } = require('../search-link.cjs');
test('the whole search term is one query value', () => {
  for (const term of ['maps & charts#west','C++','a=b&c=d','港口 50%','path/a?b=c','', 'plain']) {
    const url = new URL(searchLink(term));
    assert.equal(url.origin,'https://archive.org');
    assert.equal(url.pathname,'/search');
    assert.equal(url.hash,'');
    assert.deepEqual([...url.searchParams], [['q',term]]);
  }
});

